import { OBJECTIVES,BANDS,OPTICS,LEVELS,sciencePlan,comparisons } from './science.js';
export function scienceMarkup(d,mission){
  const p=sciencePlan(d,mission);
  return `<section class="panel science-lab"><span class="label">SCIENCE WORKBENCH${p.level?` / LEVEL ${p.level}`:' / FREE FLIGHT'}</span><h3>What will you measure?</h3><p>Match each question to an instrument, wavelength, and collection system. Payload mass, power, and downlink still count.</p><div class="objective-picker">${OBJECTIVES.map(o=>`<label><input type="checkbox" data-objective="${o.id}" ${p.objectives.includes(o.id)?'checked':''} ${p.level?'disabled':''}><span><strong>${o.name}</strong><small>${o.question}</small></span></label>`).join('')}</div>${OBJECTIVES.filter(o=>p.objectives.includes(o.id)).map(o=>`<fieldset class="science-channel"><legend>${o.instrument.toUpperCase()} ${d.payload.includes(o.instrument)?'· INSTALLED':'· NOT INSTALLED'}</legend><label>Wavelength<select data-science-instrument="${o.instrument}" data-science-field="band">${BANDS.map(([id,name])=>`<option value="${id}" ${p.channels[o.instrument].band===id?'selected':''}>${name}</option>`).join('')}</select></label><label>Optical / collection system<select data-science-instrument="${o.instrument}" data-science-field="optic">${OPTICS.map(([id,name])=>`<option value="${id}" ${p.channels[o.instrument].optic===id?'selected':''}>${name}</option>`).join('')}</select></label></fieldset>`).join('')}<p class="science-status ${p.valid?'mint':'amber'}" role="status">${p.valid?'Science configuration compatible.':p.errors.join(' ')}</p><p class="tiny muted">Required usable data: ${Math.round(p.minimum*100)}% for every selected objective, plus the mission’s overall science target. Band ranges and collection types are educational approximations.</p></section>`;
}
export function campaignMarkup(completed=[]){const next=[1,2,3].find(id=>!completed.includes(id));return `<section class="panel campaign"><span class="label">FLIGHT SCHOOL / THREE LEVELS</span><h2>Earn your lunar wings.</h2><p>Complete each level to unlock the next. Free flight remains available above.</p><div class="campaign-grid">${LEVELS.map(l=>{const locked=l.id>1&&!completed.includes(l.id-1);return `<article><span class="label">LEVEL ${l.id} · ${completed.includes(l.id)?'COMPLETED':locked?'LOCKED':'AVAILABLE'}</span><h3>${l.name}</h3><p>${l.brief}</p><small>${l.objectives.length} science objective${l.objectives.length>1?'s':''} · ${Math.round(l.coverage*100)}% usable data</small><button class="button ${l.id===next?'primary':'secondary'}" data-action="campaign" data-level="${l.id}" ${locked?'disabled':''}>${completed.includes(l.id)?'Replay level':locked?'Complete the previous level':'Begin level'}</button></article>`;}).join('')}</div></section>`;}
function product(o){
  if(o.id==='minerals')return `<svg viewBox="0 0 280 110" role="img" aria-label="Illustrative reflectance spectrum, not measured data"><path d="M25 12V90H265" fill="none" stroke="#7b868c"/><path d="M28 28 55 25 80 37 102 68 122 40 145 30 177 75 200 38 235 30 260 35" fill="none" stroke="#ffb176" stroke-width="3"/><text x="30" y="105" fill="#c4cbd0" font-size="9">0.43 µm</text><text x="225" y="105" fill="#c4cbd0" font-size="9">3 µm</text></svg>`;
  return `<svg viewBox="0 0 280 110" role="img" aria-label="Illustrative ${o.id==='terrain'?'surface mosaic':'radar intensity map'}, not measured data"><rect x="15" y="8" width="250" height="90" fill="#263239"/>${Array.from({length:24},(_,i)=>{const x=22+(i%8)*30,y=15+Math.floor(i/8)*28,v=(i*17%9)/10;return o.id==='terrain'?`<circle cx="${x+10}" cy="${y+10}" r="${4+v*7}" fill="#626b70" stroke="#9ba3a6" stroke-width="2"/>`:`<rect x="${x}" y="${y}" width="25" height="23" fill="hsl(${25+v*25} 60% ${22+v*48}%)"/>`;}).join('')}</svg>`;
}
export function scienceDebrief(f,summary){return `<section class="panel science-results"><span class="label">SCIENCE DELIVERY / ${f.design.science?.level?`LEVEL ${f.design.science.level}`:'FREE FLIGHT'}</span><h2>Did you answer the questions?</h2><div class="science-products">${summary.objectives.map(o=>`<article><span class="label ${o.met?'mint':'amber'}">${o.met?'DELIVERED':'INCOMPLETE'} · ${Math.round(o.coverage*100)}% / ${Math.round(o.target*100)}%</span><h3>${o.product}</h3>${o.met?product(o):'<div class="no-product">Insufficient data to complete this product.</div>'}<p>${o.question}</p></article>`).join('')}</div><p class="tiny muted">Product previews are synthetic illustrations, not observations or scientific findings. Coverage is a game metric derived from downlink capacity and flight decisions. Radar alone does not identify water ice.</p></section><section class="panel mission-comparisons"><span class="label">YOUR DESIGN IN CONTEXT</span><h2>Connections to real missions</h2>${comparisons(f.design).map(m=>`<article><h3>${m.name}</h3><p>${m.match}</p><p class="muted">${m.difference}</p><a href="${m.url}" target="_blank" rel="noopener noreferrer">Read the NASA instrument reference ↗</a></article>`).join('')}</section>`;}
